import React, { useMemo, useState } from "react";
import { Search, Bookmark, BookmarkCheck, ChevronDown, CheckCircle2, CircleHelp } from "lucide-react";
import { questions } from "../data/questions";

export default function Questions() {
  const [search, setSearch] = useState("");
  const [topic, setTopic] = useState("All");
  const [level, setLevel] = useState("All");
  const [revealed, setRevealed] = useState([]);
  const [saved, setSaved] = useState(() => JSON.parse(localStorage.getItem("prepai-bookmarks") || "[]"));
  const topics = ["All", ...new Set(questions.map((q) => q.topic))];
  const filtered = useMemo(() => questions.filter((q) => (topic === "All" || q.topic === topic) && (level === "All" || q.level === level) && `${q.question} ${q.topic}`.toLowerCase().includes(search.toLowerCase())), [search, topic, level]);
  const toggleSaved = (id) => {
    const next = saved.includes(id) ? saved.filter((n) => n !== id) : [...saved, id];
    setSaved(next); localStorage.setItem("prepai-bookmarks", JSON.stringify(next));
  };
  return <div className="page-stack">
    <section className="page-intro"><div><span className="eyebrow"><CircleHelp size={14} /> LEARN BY DOING</span><h2>Your question bank</h2><p>Build strong fundamentals, one question at a time.</p></div><div className="intro-count"><strong>{filtered.length}</strong><span>questions found</span></div></section>
    <div className="filter-bar"><label className="filter-search"><Search size={17} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search questions or topics..." /></label><label className="select-wrap"><span>Topic</span><select value={topic} onChange={(e) => setTopic(e.target.value)}>{topics.map((t) => <option key={t}>{t}</option>)}</select><ChevronDown size={15} /></label><label className="select-wrap"><span>Level</span><select value={level} onChange={(e) => setLevel(e.target.value)}>{["All", "Beginner", "Intermediate"].map((t) => <option key={t}>{t}</option>)}</select><ChevronDown size={15} /></label></div>
    <div className="question-list">{filtered.map((q, i) => <article className="panel question-card" key={q.id}><div className="question-top"><div className="question-tags"><span className={`topic-tag tag-${q.topic.toLowerCase()}`}>{q.topic}</span><span className="level-tag">{q.level}</span></div><button className={`icon-button bookmark-button ${saved.includes(q.id) ? "is-saved" : ""}`} onClick={() => toggleSaved(q.id)} title="Save question" aria-label="Save question">{saved.includes(q.id) ? <BookmarkCheck size={19} /> : <Bookmark size={19} />}</button></div><h3><span className="question-number">{String(i + 1).padStart(2, "0")}</span>{q.question}</h3><div className="answer-options">{q.options.map((option, index) => <div key={option} className={`answer-option ${revealed.includes(q.id) && index === q.answer ? "answer-correct" : ""}`}><span className="option-letter">{String.fromCharCode(65 + index)}</span><span>{option}</span>{revealed.includes(q.id) && index === q.answer && <CheckCircle2 size={17} />}</div>)}</div>{revealed.includes(q.id) && <div className="explanation"><strong>Explanation</strong><p>{q.explanation}</p></div>}<button className="button button-secondary reveal-button" onClick={() => setRevealed((old) => old.includes(q.id) ? old.filter((id) => id !== q.id) : [...old, q.id])}>{revealed.includes(q.id) ? "Hide explanation" : "Reveal answer & explanation"}</button></article>)}</div>
    {filtered.length === 0 && <div className="empty-state"><Search size={28} /><h3>No questions found</h3><p>Try a different keyword or filter.</p><button className="button button-secondary" onClick={() => { setSearch(""); setTopic("All"); setLevel("All"); }}>Clear filters</button></div>}
  </div>;
}
